infraSync($db,$owner,$host,$inventory);infraChange($db,$owner,$p,'infra.environment',['kind'=>'prod','name'=>'Production']);$env=(int)query($db,'SELECT id FROM infra_environments WHERE project_id=?',[$p])->fetchColumn();
